    if (_machineAuthorGuardFail(q, item, machineAuthor, owner)) return false;
    if (_mergeableGuardFail(q, item)) return false;
    if (_prStateGuardFail(q, item)) return false;
    if (_prLabelGuardsFail(q, item)) return false;
    return true;
