    if (expandedAssignee.indexOf('{machineAuthor}') !== -1 || expandedAssignee === '') return null;
    var assigneeLogins = machineAuthorModule.machineAuthorLogins(expandedAssignee);
    return assigneeLogins.length > 0 ? assigneeLogins[0] : null;
}

