function buildPrAlreadyOpenComment(ticketKey, existingUrl) {
    const m = commentMarkup.forTicket(ticketKey);
    return m.h(3, 'ℹ️ PR Already Open') + '\n\n' +
            'A pull/merge request already exists for this ticket: ' + existingUrl + '\n\n' +
