    if (alreadyFixed.rca) {
        comment += m.bold('Root Cause') + ': ' + alreadyFixed.rca + '\n\n';
    }
    if (alreadyFixed.commit) {
        comment += m.bold('Fixed in commit') + ': ' + m.code(alreadyFixed.commit) + '\n\n';
    }
    if (alreadyFixed.description) {
        comment += alreadyFixed.description + '\n\n';
    }
    if (!codeGraphUsed) {
