        openInputThreads.length, replyCoverage.unaddressed.length);
    if (lapGate.blocked) {
        return {
            blocked: true,
            result: handleReworkBlocked(scm, tracker, pr, ticketKey, statuses, fixSummary,
                openInputThreads.length, actualParams, replyCoverage.unaddressed)
