    var lapPushed = realCodeChanges === true || codeChangesCommitted === true;
    var blocked = realCodeChanges === false && openThreadCount > 0 && unaddressedCount > 0;
    var auditResolve = !blocked && openThreadCount > 0 && !lapPushed;
