// gh-1060: the blocked conclusion must park the PR too — the SM's park
// vocabulary is the PR-side `blocked` label (engine-level freeze: every
// rule carries notLabels [blocked] / matchesGuards filters it), while the
// issue-side status:Blocked is read by NO rule. Without the bridge the
// armed PR (agent:rework) re-dispatched a rework leg on every tick on a
// ticket the leg itself had declared blocked (live dart gh-395 / PR #420,
// 2026-10-18). One atomic park: label the PR `blocked` + strip the
// agent:rework / agent:review arms from BOTH carriers. Unblock is a human
// removing `blocked` from the PR (or moving the issue off status:Blocked)
// — no hidden second switch (AC2).
function parkBlockedPr(scm, tracker, pr, ticketKey) {
   var ARMS = ['agent:rework', 'agent:review'];
   if (pr && pr.number) {
       try { scm.addLabel(pr.number, 'blocked'); } catch ...
       ARMs.forEach: try scm.removeLabel(pr.number, arm)
   }
   ARMs.forEach: try tracker.removeLabel(ticketKey, arm)
}
```

