function resumeOrHandleFailedCli(ticketKey, customParams, tracker, branchName, statuses, fixSummary) {
    var failedResume = tryResumeAgent({
        ticketKey: ticketKey,
        customParams: customParams,
        section: 'postAction',
        stage: 'rework_cli_failed',
